//! Spoken credits and the AI-generated / personal-use notices.
//!
//! The opening credits play before chapter one (like Audible's intro); the
//! closing disclaimer states that the audio was generated by AI with this
//! project and Mistral's voice model, is for personal use only, and that the
//! author owns all rights. The same notice is embedded in the file metadata.

use crate::model::{BookMetadata, Credits, TtsInfo};
use crate::segment::{TITLE_PAUSE_MS, segment};

pub const PROJECT_NAME: &str = "TTS Audiobook Generator";

/// "A", "A and B", "A, B and C"; "the author" when unknown.
pub fn author_list(authors: &[String]) -> String {
    match authors {
        [] => "the author".into(),
        [a] => a.clone(),
        [rest @ .., last] => format!("{} and {last}", rest.join(", ")),
    }
}

/// `voxtral-mini-tts-2603` -> `Voxtral Mini TTS`, so the model name is
/// pronounceable.
pub fn speakable_model(model: &str) -> String {
    let words: Vec<String> = model
        .split(['-', '_', ' '])
        .filter(|p| !p.is_empty() && !p.chars().all(|c| c.is_ascii_digit()))
        .map(|p| {
            if p.len() <= 3 && p.chars().all(|c| c.is_ascii_alphabetic()) && p != "mini" {
                p.to_ascii_uppercase()
            } else {
                let mut c = p.chars();
                c.next()
                    .map(|f| f.to_uppercase().collect::<String>() + c.as_str())
                    .unwrap_or_default()
            }
        })
        .collect();
    if words.is_empty() {
        model.to_string()
    } else {
        words.join(" ")
    }
}

fn title(meta: &BookMetadata) -> String {
    let t = meta.title.clone().unwrap_or_else(|| "this book".into());
    match &meta.subtitle {
        Some(sub) => format!("{t}: {sub}"),
        None => t,
    }
}

pub fn opening_text(meta: &BookMetadata) -> String {
    format!(
        "{}. Written by {}. This audiobook was generated with artificial intelligence and is for personal use only.",
        title(meta).trim_end_matches('.'),
        author_list(&meta.authors)
    )
}

pub fn closing_text(meta: &BookMetadata, tts: &TtsInfo) -> String {
    let authors = author_list(&meta.authors);
    format!(
        "This audiobook was generated by artificial intelligence using {PROJECT_NAME}, with the {} voice model from Mistral A I. \
         It is intended for personal use only, and may not be shared, sold or distributed. \
         All rights to {} belong to {authors}. The end.",
        speakable_model(&tts.model),
        meta.title
            .as_deref()
            .unwrap_or("this book")
            .trim_end_matches('.'),
    )
}

/// One-line notice for the metadata watermark.
pub fn watermark(meta: &BookMetadata, tts: &TtsInfo) -> String {
    format!(
        "AI-generated audiobook made with {PROJECT_NAME} using Mistral AI text-to-speech (model {}, voice {}). \
         For personal use only; not for distribution or sale. All rights to the text belong to {}.",
        tts.model,
        tts.voice.as_deref().unwrap_or("default"),
        author_list(&meta.authors)
    )
}

pub fn build(meta: &BookMetadata, tts: &TtsInfo) -> Credits {
    Credits {
        opening: vec![segment(opening_text(meta), TITLE_PAUSE_MS)],
        closing: vec![segment(closing_text(meta, tts), TITLE_PAUSE_MS)],
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn meta() -> BookMetadata {
        BookMetadata {
            title: Some("The Keeper".into()),
            authors: vec!["Ingrid Solberg".into(), "Ola Nordmann".into()],
            ..Default::default()
        }
    }

    fn tts() -> TtsInfo {
        TtsInfo {
            provider: "mistral".into(),
            model: "voxtral-mini-tts-2603".into(),
            voice: Some("en_paul_neutral".into()),
            format: "flac".into(),
        }
    }

    #[test]
    fn makes_model_names_speakable() {
        assert_eq!(speakable_model("voxtral-mini-tts-2603"), "Voxtral Mini TTS");
        assert_eq!(speakable_model("2603"), "2603");
    }

    #[test]
    fn credits_mention_ai_personal_use_and_rights() {
        let open = opening_text(&meta());
        assert!(open.starts_with("The Keeper. Written by Ingrid Solberg and Ola Nordmann."));
        let close = closing_text(&meta(), &tts());
        assert!(close.contains("Voxtral Mini TTS voice model from Mistral"));
        assert!(close.contains("personal use only"));
        assert!(
            close.contains("All rights to The Keeper belong to Ingrid Solberg and Ola Nordmann.")
        );
        let mark = watermark(&meta(), &tts());
        assert!(mark.contains("model voxtral-mini-tts-2603, voice en_paul_neutral"));
        assert_eq!(author_list(&[]), "the author");
        assert_eq!(
            author_list(&["A".into(), "B".into(), "C".into()]),
            "A, B and C"
        );
    }
}
